			/*
			 * 콤보 박스에서 selection-change 이벤트 발생 시 호출.
			 * ComboBox Item을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
			 */
			function onCmb27SelectionChange(e) {
			    var cmb27 = e.control;
			    
			    var dmListParam = app.lookup("dmListParam");
			    dmListParam.clear();
			    dmListParam.setValue("unitTaskWork", cmb27.value);
			    
			    var ipb83 = app.lookup("ipb83"); // 깃플챗 아이디
			    var opt197 = app.lookup("opt197");
			    if (cmb27.value == "U11") {
			        ipb83.readOnly = false;
			        ipb83.visible = true;
			        opt197.visible = true;
			    } else {
			        ipb83.value = "";
			        ipb83.readOnly = true;
			        ipb83.visible = false;
			        opt197.visible = false;
			    }
			    
			    util.Submit.send(app, "subUnitSystemOrganization", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            var dsOrganization = app.lookup("dsOrganization");
			            
			            dsOrganization.clearFilter();
			            
			            var insertRow = dsOrganization.insertRow(dsOrganization.getRowCount() == 0 ? 0 : dsOrganization.getRowCount() - 1);
			            var newRowData = {
			                "INST_NO": "0",
			                "INST_NM": "- 해당 사항 없음 -"
			            };
			            insertRow.setRowData(newRowData);
			            
			            var dsOrgRegionSido = app.lookup("dsOrgRegionSido");
			            var dsOrgRegionSgg = app.lookup("dsOrgRegionSgg");
			            var dsOrgRegion = app.lookup("dsOrgRegion");
			            
			            dsOrgRegionSido.clear();
			            dsOrgRegionSgg.clear();
			            
			            var rowDatas = dsOrgRegion.getRowDataRanged();
			            //console.log("rowDatas.length", rowDatas.length);
			            var arrTmp = new Array();
			            for (var i = 0; i < rowDatas.length; i++) {
			                if (arrTmp.indexOf(rowDatas[i]["ENG_CTPV_NM"]) == -1) {
			                    var newRowData = {
			                        "CTPV_NM": rowDatas[i]["CTPV_NM"],
			                        "ENG_CTPV_NM": rowDatas[i]["ENG_CTPV_NM"]
			                    };
			                    //console.log("newRowData", newRowData);
			                    dsOrgRegionSido.pushRowData(newRowData);
			                    dsOrgRegionSido.commit();
			                    arrTmp.push(rowDatas[i]["ENG_CTPV_NM"]);
			                }
			            }
			            
			            var cmb26 = app.lookup("cmb26");
			            cmb26.value = "";
			            var cmb28 = app.lookup("cmb28");
			            cmb28.value = "";
			            var cmb29 = app.lookup("cmb29");
			            cmb29.value = "";
			            
			            util.Control.redraw(app, ["cmb26", "cmb28", "cmb29"]);
			        }
			    });
			    tabVisible();
			}

