			/*
			 * 추가정보 tab visible set
			 */

			function tabVisible() {
			    var dmCnterEnfsnInfo = app.lookup("dmCnterEnfsnInfo");
			    dmCnterEnfsnInfo.clear();
			    var unitCd = app.lookup("cmb27").value;
			    var orgCd = app.lookup("cmb29").value;
			    var findRow = app.lookup("dsOrganization").findFirstRow("INST_NO == '" + orgCd + "'");
			    var instTypeSeCd = "";
			    var bVisible = false;
			    if (findRow != null) {
			        instTypeSeCd = app.lookup("dsOrganization").getValue(findRow.getIndex(), "INST_TYPE_SE_CD");
			    }
			    if (unitCd == "U02" || unitCd == "U03" || unitCd == "U04" || unitCd == "U05" || unitCd == "U06") {
			        if (instTypeSeCd == "5" || instTypeSeCd == "8") {
			            bVisible = true;
			            app.lookup("opt150").value = app.lookup("cmb27").text;
			            dmCnterEnfsnInfo.setValue("CNTER_PRECON_UNT_TASKWK_SE_CD", unitCd);
			        } else {
			            bVisible = false;
			        }
			    } else {
			        bVisible = false;
			    }
			    
			    if (bVisible) {
			        app.lookup('tab1').getTabItemByID('5').visible = true;
			        app.lookup('tab1').getTabItemByID('4').visible = false;
			        app.lookup('tab1').getTabItemByID('3').visible = false;
			        app.lookup('tab1').getTabItemByID('2').visible = false;
			    } else {
			        app.lookup('tab1').getTabItemByID('5').visible = false;
			        app.lookup('tab1').getTabItemByID('4').visible = true;
			        app.lookup('tab1').getTabItemByID('3').visible = true;
			        app.lookup('tab1').getTabItemByID('2').visible = true;
			    }
			    //app.lookup("tab1").getTabItemByID("5").visible = bVisible; // 추가정보 텝 visible
			}

