			/*
			 * 인풋 박스에서 blur 이벤트 발생 시 호출.
			 * 컨트롤이 포커스를 잃은 후 발생하는 이벤트.
			 */
			function onIpb55Blur(e) {
			    var ipb55 = e.control;
			    
			    if (ValueUtil.isNull(ipb55.value)) {
			        return;
			    }
			    
			    var testStr = ipb55.value.replace(/[0-9]/g, "");
			    
			    if (!/^[a-z0-9]+$/i.test(ipb55.value)) {
			        util.Msg.alert(app, "아이디는 알파벳과 숫자로만 구성됩니다.");
			        ipb55.value = "";
			        
			    } else if (testStr.length == 0) {
			        util.Msg.alert(app, "아이디는 알파벳을 포함해야 합니다.");
			        ipb55.value = "";
			        
			    } else if (ipb55.value.length < 6 || ipb55.value.length > 30) {
			        util.Msg.alert(app, "아이디 길이는 6자 이상 30자 이하입니다.");
			        ipb55.value = "";
			    }
			}

