			function test() {
			    
			    var dmQualification = app.lookup("dmQualification");
			    
			    var cmnsinglefileupload3 = app.lookup("cmnsinglefileupload3");
			    var atfino = cmnsinglefileupload3.getAppProperty("atfino");
			    
			    //console.log("atfino", atfino);
			    
			    if (dmQualification.getValue("ATFINO") != atfino) {
			        dmQualification.setValue("ATFINO", atfino);
			    }
			    
			    //dmQualification.reset();
			    
			    //cmnsinglefileupload3.callAppMethod("removeAllFiles");
			    
			    //var cmnsinglefileview6 = app.lookup("cmnsinglefileupload6");
			    //cmnsinglefileview6.callAppMethod("removeAllFiles");
			    
			    if (dmQualification.getValue("CERTI_NM") == null || dmQualification.getValue("CERTI_NM") == "") {
			        util.Msg.alert(app, "자격증명을 입력해주시기 바랍니다.");
			        return;
			    }
			    if (!checkDate4()) {
			        return;
			    }
			    
			    var dsQualification = app.lookup("dsQualification");
			    var dmWorker = app.lookup("dmWorkerDetail");
			    
			    var qlfcInfoMngNo = dmWorker.getValue("QLFC_INFO_MNG_NO");
			    
			    if (qlfcInfoMngNo == null || qlfcInfoMngNo == "" || qlfcInfoMngNo == "0") {
			        util.Submit.send(app, "subGetQualificationNo", function(pbSuccess) {
			            if (pbSuccess) {
			                qlfcInfoMngNo = app.lookup("dmQualificationNo").getValue("QLFC_INFO_MNG_NO");
			                dmWorker.setValue("QLFC_INFO_MNG_NO", qlfcInfoMngNo);
			                setQualification(qlfcInfoMngNo);
			            }
			        });
			    } else {
			        setQualification(qlfcInfoMngNo);
			    }
			    
			}

			function checkDate4() {
			    var dmQualification = app.lookup("dmQualification");
			    var acqsYmd = dmQualification.getValue("ACQS_YMD");
			    var qlfcExpryYmd = dmQualification.getValue("QLFC_EXPRY_YMD");
			    
			    //console.log("acqsYmd", acqsYmd);
			    //console.log("qlfcExpryYmd", qlfcExpryYmd);
			    
			    if (acqsYmd != null && acqsYmd != "" && qlfcExpryYmd != null && qlfcExpryYmd != "") {
			        if (acqsYmd > qlfcExpryYmd) {
			            util.Msg.alert(app, "취득일자는 자격 만료일자보다 클 수 없습니다.");
			            return false;
			        }
			    }
			    return true;
			}

			function setQualification(qlfcInfoMngNo) {
			    
			    //console.log("qlfcInfoMngNo", qlfcInfoMngNo);
			    
			    var dmQualification = app.lookup("dmQualification");
			    var dsQualification = app.lookup("dsQualification");
			    
			    dmQualification.setValue("QLFC_INFO_MNG_NO", qlfcInfoMngNo);
			    dmQualification.setValue("DEL_YN", "N");
			    
			    //console.log("dmQualification", dmQualification.getDatas());
			    
			    var mngSn = dmQualification.getValue("QLFC_INFO_SN");
			    var checkCnt = dsQualification.getConditionalRowCount("QLFC_INFO_SN == " + (mngSn == null || mngSn == "" ? 0 : mngSn));
			    
			    if (checkCnt > 0) {
			        var stateObj = dsQualification.getRowIndicesByState(cpr.data.tabledata.RowState.UPDATED);
			        dsQualification.updateRow(stateObj[cpr.data.tabledata.RowState.UPDATED][0], dmQualification.getDatas());
			    } else {
			        var maxMngSn = dsQualification.getConditionalMax(null, "QLFC_INFO_SN");
			        //console.log("maxMngSn", maxMngSn);
			        //dmQualification.setValue("QLFC_INFO_SN", maxMngSn == null ? 1 : Number(maxMngSn) + 1);
			        dsQualification.insertRowData(0, false, dmQualification.getDatas());
			    }
			    dsQualification.commit();
			    
			    //dmQualification.reset();
			    dmQualification.clear();
			    
			    setTimeout(function() {
			        
			        var cmnsinglefileupload3 = app.lookup("cmnsinglefileupload3");
			        cmnsinglefileupload3.callAppMethod("removeAllFiles");
			        
			        var cmnsinglefileview1 = app.lookup("cmnsinglefileupload6");
			        cmnsinglefileview1.callAppMethod("removeAllFiles");
			        
			    }, 400);
			    
			    //app.lookup("btn16").click();
			    
			    util.Control.redraw(app, ["grp99"]);
			    
			    var btn17 = app.lookup("btn17");
			    btn17.value = "등록";
			    
			}

